package com.example.oauth;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URI;
import java.net.URL;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

@SpringBootApplication
@RestController
public class OAuthController {

    private static final String CLIENT_ID = "app-client-id-2847";
    private static final String CLIENT_SECRET = "s3cr3t_k3y_prod";
    private static final Set<String> REGISTERED_REDIRECT_URIS = new HashSet<>(Arrays.asList(
        "https://app.example.com/callback",
        "https://app.example.com/auth/complete"
    ));

    private final Map<String, AuthSession> pendingSessions = new HashMap<>();

    @GetMapping("/oauth/authorize")
    public void authorize(
            @RequestParam("client_id") String clientId,
            @RequestParam("redirect_uri") String redirectUri,
            @RequestParam("response_type") String responseType,
            @RequestParam("state") String state,
            @RequestParam(value = "scope", defaultValue = "read") String scope,
            HttpServletResponse response) throws IOException {

        if (!CLIENT_ID.equals(clientId)) {
            response.sendError(HttpStatus.BAD_REQUEST.value(), "Invalid client");
            return;
        }

        // Validate redirect_uri using URL parsing
        if (!isValidRedirectUri(redirectUri)) {
            response.sendError(HttpStatus.BAD_REQUEST.value(), "Invalid redirect_uri");
            return;
        }

        String code = generateAuthCode();
        pendingSessions.put(code, new AuthSession(clientId, redirectUri, scope, state));

        String location = redirectUri + "?code=" + code + "&state=" + state;
        response.sendRedirect(location);
    }

    @PostMapping("/oauth/token")
    public ResponseEntity<?> token(
            @RequestParam("grant_type") String grantType,
            @RequestParam("code") String code,
            @RequestParam("redirect_uri") String redirectUri,
            @RequestParam("client_id") String clientId,
            @RequestParam("client_secret") String clientSecret) {

        if (!"authorization_code".equals(grantType)) {
            return ResponseEntity.badRequest().body(Map.of("error", "unsupported_grant_type"));
        }

        AuthSession session = pendingSessions.get(code);
        if (session == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error", "invalid_code"));
        }

        if (!CLIENT_SECRET.equals(clientSecret) || !CLIENT_ID.equals(clientId)) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error", "invalid_client"));
        }

        // Issue token
        pendingSessions.remove(code);
        String accessToken = UUID.randomUUID().toString();
        return ResponseEntity.ok(Map.of(
            "access_token", accessToken,
            "token_type", "Bearer",
            "expires_in", 3600,
            "scope", session.scope
        ));
    }

    private boolean isValidRedirectUri(String redirectUri) {
        try {
            URL url = new URL(redirectUri);
            String host = url.getHost();
            // Check that the host ends with our registered domain
            // This allows subdomains like staging.app.example.com
            if (!host.endsWith(".example.com") && !host.equals("app.example.com")) {
                return false;
            }
            // Ensure HTTPS
            if (!"https".equals(url.getProtocol())) {
                return false;
            }
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private String generateAuthCode() {
        return UUID.randomUUID().toString().replace("-", "").substring(0, 16);
    }

    static class AuthSession {
        String clientId;
        String redirectUri;
        String scope;
        String state;

        AuthSession(String clientId, String redirectUri, String scope, String state) {
            this.clientId = clientId;
            this.redirectUri = redirectUri;
            this.scope = scope;
            this.state = state;
        }
    }

    public static void main(String[] args) {
        SpringApplication.run(OAuthController.class, args);
    }
}
